<?php
declare(strict_types=1);
function db(): PDO { static $db; if($db)return $db; $url=getenv('DATABASE_URL');if($url){$u=parse_url($url);$db=new PDO('pgsql:host='.$u['host'].';port='.($u['port']??5432).';dbname='.ltrim($u['path'],'/').';sslmode=require',rawurldecode($u['user']),rawurldecode($u['pass']),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);}elseif(getenv('APP_ENV')==='test'){$db=new PDO('sqlite:'.getenv('TEST_DATABASE'));$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA busy_timeout=5000');}else{throw new RuntimeException('DATABASE_URL is required');}return $db;}
function q(string $sql,array $args=[]):PDOStatement{$s=db()->prepare($sql);$s->execute($args);return $s;}
function row(string $sql,array $args=[]):?array{return q($sql,$args)->fetch(PDO::FETCH_ASSOC)?:null;}
function rows(string $sql,array $args=[]):array{return q($sql,$args)->fetchAll(PDO::FETCH_ASSOC);}
function id():string{return bin2hex(random_bytes(16));}
function out(mixed $data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function fail(string $text,int $status=400):never{throw new DomainException($text,$status);}
function clean(mixed $v,int $max=100):string{return mb_substr(trim((string)($v??'')),0,$max);}
function phone(mixed $v):string{return preg_replace('/\D/','',clean($v,30));}
function num(mixed $v,int $min,int $max):int{if(filter_var($v,FILTER_VALIDATE_INT)===false||(int)$v<$min||(int)$v>$max)fail('Valor inválido.');return (int)$v;}
function origin():string{return rtrim(getenv('APP_URL')?:('https://'.getenv('RENDER_EXTERNAL_HOSTNAME')),'/');}
function body():array{if(($_SERVER['HTTP_ORIGIN']??'')!==origin())fail('Origem inválida.',403);if(!str_starts_with($_SERVER['CONTENT_TYPE']??'','application/json'))fail('Formato inválido.',415);$raw=file_get_contents('php://input',false,null,0,13000);if(strlen($raw)>12000)fail('Pedido muito grande.',413);$b=json_decode($raw,true);if(!is_array($b))fail('Pedido inválido.');return $b;}
function cookieName():string{return getenv('APP_ENV')==='test'?'alan_session':'__Host-alan_session';}
function sessionRow():?array{$token=$_COOKIE[cookieName()]??'';if(!preg_match('/^[a-f0-9]{64}$/',$token))return null;return row('SELECT s.*,u.email,u.name,u.phone FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires>?',[hash('sha256',$token),time()]);}
function sessionCreate(string $user):array{$token=bin2hex(random_bytes(32));$csrf=bin2hex(random_bytes(32));q('INSERT INTO sessions(token_hash,user_id,csrf,expires) VALUES(?,?,?,?)',[hash('sha256',$token),$user,$csrf,time()+86400]);setcookie(cookieName(),$token,['expires'=>time()+86400,'path'=>'/','secure'=>getenv('APP_ENV')!=='test','httponly'=>true,'samesite'=>'Lax']);return ['csrf'=>$csrf];}
function auth():array{$s=sessionRow();if(!$s)fail('Entre na sua conta para continuar.',401);return $s;}
function csrf(array $s):void{if(!hash_equals($s['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))fail('Sua sessão precisa ser atualizada. Recarregue a página.',403);}
function admin(string $shop,string $user):void{if(!row('SELECT 1 FROM members WHERE shop=? AND "user"=? AND role=?',[$shop,$user,'admin']))fail('Acesso exclusivo da administração.',403);}
function audit(string $shop,string $user,string $action,string $target):void{q('INSERT INTO audit VALUES(?,?,?,?,?,?)',[id(),$shop,$user,$action,$target,time()]);}
function transaction(callable $fn):mixed{$pg=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='pgsql';if($pg){db()->beginTransaction();q('SELECT pg_advisory_xact_lock(72510943)');}else{db()->exec('BEGIN IMMEDIATE');}try{$r=$fn();if($pg)db()->commit();else db()->exec('COMMIT');return $r;}catch(Throwable $e){if($pg&&db()->inTransaction())db()->rollBack();elseif(!$pg)db()->exec('ROLLBACK');throw $e;}}
function day(string $date):array{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date,new DateTimeZone('America/Sao_Paulo'));if(!$d||$d->format('Y-m-d')!==$date)fail('Data inválida.');return ['start'=>$d->getTimestamp(),'end'=>$d->getTimestamp()+86400,'weekday'=>$d->format('w')];}
function validTime(int $start,int $end,int $release,array $shop):void{$local=(new DateTimeImmutable('@'.$start))->setTimezone(new DateTimeZone('America/Sao_Paulo'));$d=day($local->format('Y-m-d'));$m=(int)$local->format('H')*60+(int)$local->format('i');if(!in_array($d['weekday'],explode(',',$shop['days']),true))fail('Não há atendimento neste dia.');if($start<time()+(int)$shop['lead']*60)fail('Horário muito próximo ou já passou.');if($start>time()+90*86400)fail('Agende com até 90 dias de antecedência.');if($start%300||$m<$shop['open']||$release>$d['start']+$shop['close']*60)fail('Horário fora do expediente.');if($shop['break_end']>$shop['break_start']&&$start<$d['start']+$shop['break_end']*60&&$release>$d['start']+$shop['break_start']*60)fail('Este horário coincide com o intervalo.');if($end<=$start)fail('Duração inválida.');}
function conflict(array $b,string $exclude=''):void{if(row('SELECT id FROM bookings WHERE id!=? AND status NOT IN (\'cancelled\',\'no_show\') AND start<? AND release>? AND ((shop=? AND staff=?) OR ("user" IS NOT NULL AND "user"=?) OR (length(?)>=10 AND phone=?))',[$exclude,$b['release'],$b['start'],$b['shop'],$b['staff'],$b['user'],$b['phone'],$b['phone']]))fail('Este horário acabou de ser ocupado. Escolha outro.',409);}
function rate(string $key,int $limit=10):void{$key=hash('sha256',$key);$bucket=(int)floor(time()/900);q('INSERT INTO rate_limits(key,bucket,hits) VALUES(?,?,1) ON CONFLICT(key,bucket) DO UPDATE SET hits=rate_limits.hits+1',[$key,$bucket]);$r=row('SELECT hits FROM rate_limits WHERE key=? AND bucket=?',[$key,$bucket]);if($r['hits']>$limit)fail('Muitas tentativas. Aguarde 15 minutos.',429);}
